test:
bad_calls = [
    lambda: simulate_recovery([], 1),
    lambda: simulate_recovery([[1], [0, 1]], 1),
    lambda: simulate_recovery([[3]], 1),
    lambda: simulate_recovery([[1]], 0),
    lambda: simulate_recovery([[1]], 1, infection_threshold=0),
]
for call in bad_calls:
    try:
        call()
        assert False, 'expected ValueError'
    except ValueError:
        pass
